CREATE TRIGGER cap_total_boards BEFORE INSERT ON boards WHEN (SELECT count(*) FROM boards)>=100 BEGIN SELECT RAISE(ABORT,'Global board capacity reached'); END;
CREATE TRIGGER cap_event_storage BEFORE INSERT ON board_events BEGIN INSERT INTO quotas(key,used) VALUES('event-bytes',length(CAST(NEW.payload AS BLOB))) ON CONFLICT(key) DO UPDATE SET used=used+excluded.used; SELECT RAISE(ABORT,'Global event storage budget reached') WHERE (SELECT used FROM quotas WHERE key='event-bytes')>52428800; INSERT INTO quotas(key,used) VALUES('event-count',1) ON CONFLICT(key) DO UPDATE SET used=used+1; SELECT RAISE(ABORT,'Global event count budget reached') WHERE (SELECT used FROM quotas WHERE key='event-count')>20000; END;
